local RecorderMaker = {}
local PRODUCTS = {
    soprano_recorder = { name = "Soprano flavta", woodCost = 1, time = 1, cost = 12, soundQuality = 8, prestige = 1, description = "Preprosta soprano flavta za učence." },
    alto_recorder = { name = "Alt flavta", woodCost = 2, time = 2, cost = 35, soundQuality = 11, prestige = 2, description = "Alt flavta za dvorne koncerte." },
    tenor_recorder = { name = "Tenor flavta", woodCost = 2, brassCost = 1, time = 4, cost = 90, soundQuality = 14, prestige = 4, happiness = 1, description = "Tenor flavta z medeninastim koncem." },
    bass_recorder = { name = "Bas flavta", woodCost = 3, brassCost = 1, time = 6, cost = 220, soundQuality = 18, prestige = 7, happiness = 2, description = "Bas flavta s kljunom in medeninastim okovjem." },
    ivory_recorder = { name = "Slonokoščena flavta", ivoryCost = 1, woodCost = 1, time = 8, cost = 480, soundQuality = 22, prestige = 12, happiness = 3, description = "Slonokoščena flavta za plemiške dvorane." },
    royal_consort_recorder = { name = "Kraljevski konzort flavta", ivoryCost = 2, silverCost = 1, goldCost = 1, jewelCost = 1, time = 12, cost = 1500, soundQuality = 34, prestige = 38, happiness = 8, description = "Velika kraljevska konzort flavta z zlatim okovjem in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Flavtarska delavnica", cost = { gold = 240, wood = 120 }, upkeep = 6, qualityBonus = 5 },
    boring_room = { name = "Vrtalnica", cost = { gold = 750, wood = 220, stone = 200, brass = 6 }, upkeep = 18, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, ivory = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_recorder_atelier = { name = "Kraljevski atelje flavt", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, ivory = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
RecorderMaker.woodStock = 14; RecorderMaker.brassStock = 8; RecorderMaker.ivoryStock = 8; RecorderMaker.silverStock = 6; RecorderMaker.goldStock = 6; RecorderMaker.jewelStock = 4
RecorderMaker.productStock = {}; RecorderMaker.buildings = {}; RecorderMaker.maker = nil; RecorderMaker.activeMaking = {}; RecorderMaker.totalProducts = 0; RecorderMaker.dayTimer = 0
function RecorderMaker.init() RecorderMaker.woodStock=14; RecorderMaker.brassStock=8; RecorderMaker.ivoryStock=8; RecorderMaker.silverStock=6; RecorderMaker.goldStock=6; RecorderMaker.jewelStock=4; RecorderMaker.productStock={}; RecorderMaker.buildings={}; RecorderMaker.maker=nil; RecorderMaker.activeMaking={}; RecorderMaker.totalProducts=0; RecorderMaker.dayTimer=0; print("[RecorderMaker] Royal Recorder Maker System initialized (6 products, 4 buildings)") end
function RecorderMaker.hireMaker(n,s) s=s or math.random(50,90); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RecorderMaker.maker={name=n or ("Flavtar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Flavtar najet: %s (spretnost: %d)",RecorderMaker.maker.name,s),"success") end; return true end
function RecorderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RecorderMaker.build(id) local ok,e=RecorderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RecorderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RecorderMaker.getQualityBonus() local b=0; for _,bd in ipairs(RecorderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RecorderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and RecorderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and RecorderMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.ivoryCost and RecorderMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.silverCost and RecorderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RecorderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RecorderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #RecorderMaker.buildings==0 then return false,"Potrebna delavnica" end; if not RecorderMaker.maker then return false,"Potreben flavtar" end; return true end
function RecorderMaker.make(pt,qty) qty=qty or 1; local ok,e=RecorderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then RecorderMaker.woodStock=RecorderMaker.woodStock-d.woodCost*qty end; if d.brassCost then RecorderMaker.brassStock=RecorderMaker.brassStock-d.brassCost*qty end; if d.ivoryCost then RecorderMaker.ivoryStock=RecorderMaker.ivoryStock-d.ivoryCost*qty end; if d.silverCost then RecorderMaker.silverStock=RecorderMaker.silverStock-d.silverCost*qty end; if d.goldCost then RecorderMaker.goldStock=RecorderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RecorderMaker.jewelStock=RecorderMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if RecorderMaker.maker then t=math.max(1,t-math.floor(RecorderMaker.maker.skill/12)) end; table.insert(RecorderMaker.activeMaking,{id="recorder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RecorderMaker.completeMaking(m) local q=1.0+(RecorderMaker.getQualityBonus()/100); if RecorderMaker.maker then q=q+(RecorderMaker.maker.skill/180) end; q=math.min(2.0,q); RecorderMaker.productStock[m.productType]=(RecorderMaker.productStock[m.productType] or 0)+m.quantity; RecorderMaker.totalProducts=RecorderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RecorderMaker.maker then RecorderMaker.maker.itemsMade=RecorderMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then RecorderMaker.maker.skill=math.min(100,RecorderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Flavta izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"recorder.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function RecorderMaker.update(dt) if not _G.state then return end; RecorderMaker.dayTimer=RecorderMaker.dayTimer+dt; if RecorderMaker.dayTimer>=30 then RecorderMaker.dayTimer=0; for i=#RecorderMaker.activeMaking,1,-1 do local m=RecorderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RecorderMaker.completeMaking(m); table.remove(RecorderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RecorderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RecorderMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RecorderMaker.getStats() return {woodStock=RecorderMaker.woodStock,brassStock=RecorderMaker.brassStock,ivoryStock=RecorderMaker.ivoryStock,silverStock=RecorderMaker.silverStock,goldStock=RecorderMaker.goldStock,jewelStock=RecorderMaker.jewelStock,productStock=RecorderMaker.productStock,numBuildings=#RecorderMaker.buildings,hasMaker=RecorderMaker.maker~=nil,makerName=RecorderMaker.maker and RecorderMaker.maker.name or "—",makerSkill=RecorderMaker.maker and RecorderMaker.maker.skill or 0,activeMaking=#RecorderMaker.activeMaking,totalProducts=RecorderMaker.totalProducts} end
return RecorderMaker
